    /// W2-1:结构指纹必须覆盖组合键表 —— 成员键/动作类型/数量一变就变,
    /// 只改动作的几何参数(坐标/半径)不算结构变化。
    #[test]
    fn combos_signature_tracks_membership_and_action_kind() {
        let mut p = Profile::default();
        p.combos.push(KeyCombo {
            keys: vec![29, 19],
            action: Action::Hold {
                x: 0.5,
                y: 0.5,
                radius: 0.03,
            },
            fps_only: false,
        });
        let c0 = combos_signature(&p.combos);
        // 只改坐标/半径:不是结构变化,不该触发抬手重建
        p.combos[0].action = Action::Hold {
            x: 0.1,
            y: 0.9,
            radius: 0.09,
        };
        assert_eq!(combos_signature(&p.combos), c0, "只改坐标不算结构变化");
        // 换成员键 / 换动作类型 / 增删组合:索引会整体位移,必须识别出来
        p.combos[0].keys = vec![29, 20];
        assert_ne!(combos_signature(&p.combos), c0, "换成员键必须触发重建");
        let c1 = combos_signature(&p.combos);
        p.combos[0].action = Action::Tap {
            x: 0.5,
            y: 0.5,
            duration_ms: 40,
            radius: 0.03,
        };
        assert_ne!(combos_signature(&p.combos), c1, "换动作类型必须触发重建");
        let c2 = combos_signature(&p.combos);
        p.combos.push(KeyCombo {
            keys: vec![30],
            action: Action::AndroidKey { keycode: 4 },
            fps_only: false,
        });
        assert_ne!(combos_signature(&p.combos), c2, "增删组合必须触发重建");
        p.combos.pop();
        assert_eq!(combos_signature(&p.combos), c2, "加回同一组应回到同一指纹");
    }

    /// W2-1:关掉"组合键启用"开关 = 门控被整体清空,必须先把正按着的那一组
    /// 补出一条抬起事件 —— 否则 Hold 类组合(以及组合触发的系统键)会永远
    /// 按在设备上,`combo_fingers.count` 虚高把十指预算吃掉一格。
    #[test]
    fn combo_gate_emits_release_when_combos_disabled() {
        let mut profile = Profile::default();
        profile.combos_enabled = true;
        profile.combos.push(KeyCombo {
            keys: vec![29, 19],
            action: Action::Hold {
                x: 0.5,
                y: 0.5,
                radius: 0.03,
            },
            fps_only: false,
        });
        let mut gate = ComboGate::default();
        assert!(
            gate.ingest_button(
                CaptureKey {
                    code: 29,
                    pressed: true,
                },
                &profile,
                &[]
            )
            .is_none()
        );
        let on = gate
            .ingest_button(
                CaptureKey {
                    code: 19,
                    pressed: true,
                },
                &profile,
                &[],
            )
            .expect("完整组合应立即触发");
        assert!(matches!(
            on,
            EngineInput::Combo {
                index: 0,
                pressed: true
            }
        ));

        // 用户把"组合键启用"关掉:下一次轮询必须补一条抬起
        profile.combos_enabled = false;
        let off = gate
            .poll(&profile)
            .expect("关闭组合键开关时必须补发抬起事件");
        assert!(matches!(
            off,
            EngineInput::Combo {
                index: 0,
                pressed: false
            }
        ));
        // 抬起只补一次,不能每次轮询都补
        assert!(gate.poll(&profile).is_none(), "补发必须幂等");
    }

    /// W2-1:reset(换方案、关映射收尾都走它)遵守同一条不变量 ——
    /// 清掉按着的组合必须留下抬起事件;没有组合按着时不产生幽灵事件。
    #[test]
    fn combo_gate_reset_requeues_release_of_active_combo() {
        let mut profile = Profile::default();
        profile.combos_enabled = true;
        profile.combos.push(KeyCombo {
            keys: vec![29, 19],
            action: Action::Hold {
                x: 0.5,
                y: 0.5,
                radius: 0.03,
            },
            fps_only: false,
        });
        let mut gate = ComboGate::default();
        let _ = gate.ingest_button(
            CaptureKey {
                code: 29,
                pressed: true,
            },
            &profile,
            &[],
        );
        let on = gate
            .ingest_button(
                CaptureKey {
                    code: 19,
                    pressed: true,
                },
                &profile,
                &[],
            )
            .expect("完整组合应立即触发");
        assert!(matches!(
            on,
            EngineInput::Combo {
                index: 0,
                pressed: true
            }
        ));

        gate.reset();
        let off = gate.poll(&profile).expect("reset 必须留下一条抬起");
        assert!(matches!(
            off,
            EngineInput::Combo {
                index: 0,
                pressed: false
            }
        ));

        // 空门控 reset 后不得凭空冒出事件
        gate.reset();
        assert!(
            gate.poll(&profile).is_none(),
            "没有按着的组合时 reset 是纯清理"
        );
    }

    #[test]
    fn virtual_gamepad_report_layout_matches_scrcpy_descriptor() {
        let report = gamepad_report(65535.0, 0.0);
        assert_eq!(&report[0..2], &32768u16.to_le_bytes(), "left x centered");
        assert_eq!(&report[2..4], &32768u16.to_le_bytes(), "left y centered");
        assert_eq!(&report[4..6], &65535u16.to_le_bytes(), "right x max");
        assert_eq!(&report[6..8], &0u16.to_le_bytes(), "right y min");
        assert_eq!(&report[8..15], &[0u8; 7], "triggers/buttons/hat neutral");
    }

    #[test]
    fn gamepad_center_matches_scrcpy_neutral() {
        let report = gamepad_report(GAMEPAD_AXIS_CENTER, GAMEPAD_AXIS_CENTER);
        assert_eq!(
            &report[0..8],
            &[0x00, 0x80, 0x00, 0x80, 0x00, 0x80, 0x00, 0x80],
            "left/right sticks must use scrcpy's 0x8000 neutral value"
        );
    }

    #[test]
    fn gamepad_modes_are_recognized_without_anchor() {
        let mut aim = aim_at(0.0, 0.0);
        aim.input_mode = ViewInputMode::VirtualGamepadSegmented;
        aim.enabled = true;
        let st = AimState {
            mode_active: true,
            ..Default::default()
        };
        assert!(gamepad_active(&aim, &st));
        assert!(!aim_active(&aim, &st));
    }

    /// W2-8:录制步骤照时间轴逐条重放(同一配对的按下/抬起共用一个触点号),
    /// 设置步骤自包含展开。触点号按执行实例分段,步骤之间互不撞车。
    #[test]
    fn macro_schedule_replays_timeline_and_expands_instructions() {
        use crate::keymap::{DEFAULT_RADIUS, MacroStep};

        let m = mapper();
        let mut profile = Profile::default();
        profile.binds.push(KeyBind {
            key: 18,
            action: Action::Tap {
                x: 0.2,
                y: 0.3,
                duration_ms: 40,
                radius: DEFAULT_RADIUS,
            },
            fps_only: false,
        });
        // 绑定键刻意避开默认轮盘的 W/S/A/D —— 那些键归轮盘(方向键覆盖绑定)
        profile.binds.push(KeyBind {
            key: 16,
            action: Action::Tap {
                x: 0.4,
                y: 0.5,
                duration_ms: 40,
                radius: DEFAULT_RADIUS,
            },
            fps_only: false,
        });
        let action = MacroAction {
            virtual_profile: None,
            steps: vec![
                MacroStep {
                    code: 18,
                    pressed: true,
                    delay_ms: 0,
                },
                MacroStep {
                    code: 18,
                    pressed: false,
                    delay_ms: 80,
                },
            ],
            instructions: vec![
                MacroInstruction::Key {
                    code: 16,
                    duration_ms: 100,
                    delay_ms: 10,
                },
                MacroInstruction::Wheel {
                    wheel: 0,
                    part: MacroWheelPart::Right,
                    duration_ms: 50,
                    delay_ms: 20,
                },
                MacroInstruction::Click {
                    x: 0.5,
                    y: 0.5,
                    duration_ms: 40,
                    delay_ms: 0,
                },
            ],
        };
        let start = Instant::now();
        let mut scheduled = Vec::new();
        let duration = schedule_macro(
            &action,
            &profile,
            &m,
            start,
            &mut scheduled,
            &mut MacroPlan::new(0),
        );
        assert_eq!(duration, 80 + 10 + 100 + 20 + 50 + 40);

        let clicks: Vec<(Instant, bool, u64)> = scheduled
            .iter()
            .filter_map(|(t, a)| match a {
                SchedAct::MacroClick { pid, down, .. } => Some((*t, *down, *pid)),
                _ => None,
            })
            .collect();
        assert_eq!(
            clicks.len(),
            6,
            "录制 1 对 + 按键 1 对 + 点击 1 对: {clicks:?}"
        );
        let (rec, key, click) = (clicks[0].2, clicks[2].2, clicks[4].2);
        assert_ne!(rec, key);
        assert_ne!(key, click);
        assert_eq!(
            clicks,
            vec![
                (start, true, rec),
                (start + Duration::from_millis(80), false, rec),
                (start + Duration::from_millis(90), true, key),
                (start + Duration::from_millis(190), false, key),
                (start + Duration::from_millis(260), true, click),
                (start + Duration::from_millis(300), false, click),
            ],
            "录制照时间轴重放、设置步骤自包含、同刻顺序由排程序号钉死"
        );

        let wheels: Vec<(Instant, bool)> = scheduled
            .iter()
            .filter_map(|(t, a)| match a {
                SchedAct::MacroWheel { down, .. } => Some((*t, *down)),
                _ => None,
            })
            .collect();
        assert_eq!(
            wheels,
            vec![
                (start + Duration::from_millis(210), true),
                (start + Duration::from_millis(260), false),
            ],
            "活轮盘设置步骤走 MacroWheel 的按下/抬起"
        );
    }

    /// W2-8:"按键"设置步骤是自包含的"按下 → 持续 → 抬起",后面的等待照旧;
    /// 宏不需要长按 —— 步骤不会把触点保持到宏结束。
    #[test]
    fn macro_key_step_is_self_contained() {
        use crate::keymap::DEFAULT_RADIUS;

        let m = mapper();
        let mut profile = Profile::default();
        profile.wheels.clear();
        profile.binds.push(KeyBind {
            key: 30,
            action: Action::Hold {
                x: 0.5,
                y: 0.5,
                radius: DEFAULT_RADIUS,
            },
            fps_only: false,
        });
        let action = MacroAction {
            virtual_profile: None,
            steps: Vec::new(),
            instructions: vec![
                MacroInstruction::Key {
                    code: 30,
                    duration_ms: 100,
                    delay_ms: 0,
                },
                MacroInstruction::Delay { ms: 500 },
            ],
        };
        let start = Instant::now();
        let mut scheduled = Vec::new();
        let total = schedule_macro(
            &action,
            &profile,
            &m,
            start,
            &mut scheduled,
            &mut MacroPlan::new(0),
        );
        assert_eq!(total, 600);
        let acts: Vec<(Instant, bool)> = scheduled
            .iter()
            .filter_map(|(t, a)| match a {
                SchedAct::MacroClick { down, .. } => Some((*t, *down)),
                _ => None,
            })
            .collect();
        assert_eq!(
            acts,
            vec![(start, true), (start + Duration::from_millis(100), false)],
            "自包含:按下后 duration_ms 就抬起,而不是拖到宏结束"
        );
    }

    /// W2-8:同一宏里同键"先抬后按"必须严格按时间轴顺序发出(同刻动作的先后
    /// 由排程序号钉死),且两次按下用不同触点号。
    #[test]
    fn macro_recorded_repress_orders_release_before_press() {
        use crate::keymap::{DEFAULT_RADIUS, MacroStep};

        let m = mapper();
        let mut profile = Profile::default();
        profile.wheels.clear();
        profile.binds.push(KeyBind {
            key: 30,
            action: Action::Tap {
                x: 0.5,
                y: 0.5,
                duration_ms: 40,
                radius: DEFAULT_RADIUS,
            },
            fps_only: false,
        });
        let action = MacroAction {
            virtual_profile: None,
            steps: vec![
                MacroStep {
                    code: 30,
                    pressed: true,
                    delay_ms: 0,
                },
                MacroStep {
                    code: 30,
                    pressed: false,
                    delay_ms: 50,
                },
                // 录成"抬起的同刻又按下"(连续两次点击被合并到同一毫秒):
                // 排程必须把抬起排在按下之前。
                MacroStep {
                    code: 30,
                    pressed: true,
                    delay_ms: 0,
                },
                MacroStep {
                    code: 30,
                    pressed: false,
                    delay_ms: 30,
                },
            ],
            instructions: Vec::new(),
        };
        let start = Instant::now();
        let mut scheduled = Vec::new();
        schedule_macro(
            &action,
            &profile,
            &m,
            start,
            &mut scheduled,
            &mut MacroPlan::new(0),
        );
        let acts: Vec<(Instant, bool, u64)> = scheduled
            .iter()
            .filter_map(|(t, a)| match a {
                SchedAct::MacroClick { pid, down, .. } => Some((*t, *down, *pid)),
                _ => None,
            })
            .collect();
        let (first, second) = (acts[0].2, acts[2].2);
        assert_ne!(first, second, "两次按下必须是两个触点号");
        let t50 = start + Duration::from_millis(50);
        assert_eq!(
            acts,
            vec![
                (start, true, first),
                (t50, false, first),
                (t50, true, second),
                (start + Duration::from_millis(80), false, second),
            ],
            "同刻必须是先抬后按"
        );
    }

    /// W2-8:虚拟层("扩展宏")的录制步骤按虚拟配置解析、照录制时刻抬起 ——
    /// 不再依赖这些键位存在于当前配置,也不再让事件重新进入输入流。
    #[test]
    fn macro_recorded_steps_resolve_through_virtual_profile() {
        use crate::keymap::{DEFAULT_RADIUS, MacroStep};

        let m = mapper();
        let mut virtual_profile = Profile::default();
        virtual_profile.wheels.clear();
        virtual_profile.binds.push(KeyBind {
            key: 18,
            action: Action::Tap {
                x: 0.2,
                y: 0.3,
                duration_ms: 40,
                radius: DEFAULT_RADIUS,
            },
            fps_only: false,
        });
        let action = MacroAction {
            steps: vec![
                MacroStep {
                    code: 18,
                    pressed: true,
                    delay_ms: 0,
                },
                MacroStep {
                    code: 18,
                    pressed: false,
                    delay_ms: 200,
                },
            ],
            instructions: Vec::new(),
            virtual_profile: Some(Box::new(virtual_profile)),
        };
        let start = Instant::now();
        let mut scheduled = Vec::new();
        schedule_macro(
            &action,
            // 当前配置里没有这个键位 —— 虚拟层必须自给自足
            &Profile::default(),
            &m,
            start,
            &mut scheduled,
            &mut MacroPlan::new(0),
        );
        let clicks: Vec<(Instant, bool, f32, f32, u64)> = scheduled
            .iter()
            .filter_map(|(t, a)| match a {
                SchedAct::MacroClick {
                    pid, x, y, down, ..
                } => Some((*t, *down, *x, *y, *pid)),
                _ => None,
            })
            .collect();
        assert_eq!(clicks.len(), 2, "虚拟层录制步骤:1 按下 + 1 抬起 {clicks:?}");
        assert_eq!(clicks[0].0, start);
        assert!(clicks[0].1, "先按下");
        assert!((clicks[0].2 - 0.2).abs() < 1e-6 && (clicks[0].3 - 0.3).abs() < 1e-6);
        assert_eq!(
            clicks[1].0,
            start + Duration::from_millis(200),
            "照录制时刻抬起"
        );
        assert!(!clicks[1].1);
        assert_eq!(clicks[0].4, clicks[1].4, "同一配对的触点号必须一致");
    }

    /// W2-8:录制里没等到抬起的按下(录制中断)在宏结尾兜底抬起 ——
    /// 宏结束后设备上不留任何按着的触点。
